#!/usr/bin/python3

"""
    Reporting support module private methods.
"""

__author__ = "Velocity Support"
__email__ = "velocity.support@nokia.com"

from velocity_communicator.log.log import Log


class ReportingPrivate(object):
    """
        Class with definicion of private methods related to
        Reporting module.
    """

    logger = Log.get_logger("velocityclient")

    def _device_reservation_report_message(self, device_name, res_name, res_id):
        server = self.get_server_address()
        html = """
            <!doctype html>
            <html>
            <head>
                <meta http-equiv="Content-Type" content="text/html; charset=UTF-8">
            </head>
            <body style="font-family: sans-serif;">
                <div style="display: block; margin: auto; max-width: 600px;" class="main">
                <h1 style="font-size: 18px; font-weight: bold; margin-top: 20px">
                    Device """ + device_name + """ is reserved as """ + res_name + """!</h1>

                <p>Please, check reservation:<br>
                <p>""" + server + """/velocity/schedule/reservations/""" + res_id + """/info</p>

                <p>Br,<br>
                Velocity Support</p>
                </div>
                <style>
                .main { background-color: white; }
                a:hover { border-left-width: 1em; min-height: 2em; }
                </style>
            </body>
            </html>
            """
        return html

    def _token_expiration_message(self, expiration_time, hostname):
        server = self.get_server_address()
        hours = int(expiration_time // 3600)
        minutes = int((expiration_time % 3600) // 60)
        html = """
            <!doctype html>
            <html>
            <head>
                <meta http-equiv="Content-Type" content="text/html; charset=UTF-8">
            </head>
            <body style="font-family: sans-serif;">
                <div style="display: block; margin: auto; max-width: 600px;" class="main">
                <h1 style="font-size: 18px; font-weight: bold; margin-top: 20px">
                    Velocity token is going to expire in """ + str(hours) + """ hours and """ + str(minutes) + """ minutes on host """ + hostname + """!</h1>

                <p>Please, generate a new token from """ + server + """ and update the token in your environment to avoid authentication issues!<br>

                <p>Br,<br>
                Velocity Support</p>
                </div>
                <style>
                .main { background-color: white; }
                a:hover { border-left-width: 1em; min-height: 2em; }
                </style>
            </body>
            </html>
            """
        return html
